## 3. Result-Generation Logic (form data → recommendation)

Source: `client/src/lib/ulcerativeColitisLogic.ts`

```typescript
/**
 * Ulcerative Colitis Clinical Logic Engine
 * Based on: ACG Clinical Guideline: Ulcerative Colitis in Adults (2019, 2025 Update)
 *           AGA Living Clinical Practice Guideline on the Management of Moderate-to-Severe UC (2025)
 *           ECCO Consensus on UC Management (2024)
 * Key decisions: Disease extent/severity (Montreal), 5-ASA vs biologic selection,
 *                IL-23, JAK, S1P mechanism-based selection, acute severe UC management,
 *                colectomy decision-making
 */

export type UCExtent = 'proctitis' | 'left_sided' | 'extensive' | 'pancolitis';
export type UCSeverity = 'mild' | 'moderate' | 'severe' | 'acute_severe';
export type UCPriorTherapy =
  | 'none'
  | 'on_5asa'
  | 'failed_5asa'
  | 'on_immunomodulator'
  | 'failed_immunomodulator'
  | 'failed_anti_tnf'
  | 'failed_vedolizumab'
  | 'failed_multiple_biologics';

export type MayoScore = 'remission' | 'mild' | 'moderate' | 'severe'; // Mayo 0-1, 2-4, 5-7, 8-12

export interface UlcerativeColitisInput {
  // Disease characterization
  extent: UCExtent;
  severity: UCSeverity;
  mayoScore?: number; // 0–12 (full Mayo) or 0–9 (partial Mayo)
  endoscopicSubscore?: number; // 0–3 (Mayo endoscopic subscore)
  hasBloodyStools: boolean;
  stoolFrequencyPerDay: number;
  hasNocturnalSymptoms: boolean;

  // Disease activity markers
  crpMgL?: number;
  fcalUgG?: number; // Fecal calprotectin
  hasAnemia: boolean;
  albuminGdL?: number;

  // Prior therapy
  priorTherapy: UCPriorTherapy;
  currentBiologic?: string;
  hasLostResponseToBiologic: boolean;
  hasAntiDrugAntibodies: boolean;
  isOnSteroids: boolean;
  isSteroidDependent: boolean; // unable to taper without flare
  isSteroidRefractory: boolean; // no response to IV steroids in 3–5 days (acute severe UC)

  // Comorbidities affecting therapy selection
  hasActiveTB: boolean;
  hasLatentTB: boolean;
  hasHepatitisB: boolean;
  hasMalignancyHistory: boolean;
  hasDemyelinatingDisease: boolean;
  hasCongestiveHeartFailure: boolean;
  isPregnantOrPlanning: boolean;
  hasJAKContraindication: boolean; // DVT/PE history, CV risk, malignancy
  hasThromboembolismHistory: boolean; // relevant for tofacitinib/upadacitinib
  hasCardiovascularRisk: boolean; // relevant for JAK inhibitors

  // Acute severe UC specific
  isHospitalized: boolean;
  daysOnIVSteroids?: number; // for rescue therapy decision
  hasColonDilation: boolean; // toxic megacolon
  hasPerforation: boolean;

  // Patient preferences
  prefersOralTherapy: boolean;
  prefersSubcutaneous: boolean;
  wantsRapidOnset: boolean; // relevant for JAK inhibitors
}

export interface UlcerativeColitisRecommendation {
  primaryRecommendation: string;
  inductionTherapy: string;
  maintenanceTherapy: string;
  biologicSelection: string;
  acuteSevereUCPlan: string;
  colectomyConsideration: string;
  urgentFlags: string[];
  recommendedAgents: string[];
  agentsToAvoid: string[];
  monitoringPlan: string;
  nextSteps: string[];
  evidenceLevel: 'A' | 'B' | 'C';
  rationale: string;
  references: Array<{ citation: string; pmid?: string; url?: string }>;
}

export function assessUlcerativeColitis(input: UlcerativeColitisInput): UlcerativeColitisRecommendation {
  const urgentFlags: string[] = [];
  const recommendedAgents: string[] = [];
  const agentsToAvoid: string[] = [];
  const nextSteps: string[] = [];

  // ─── Urgent Flags ─────────────────────────────────────────────────────────
  if (input.hasPerforation) {
    urgentFlags.push('BOWEL PERFORATION: emergency surgical consultation — colectomy required urgently');
  }
  if (input.hasColonDilation) {
    urgentFlags.push('TOXIC MEGACOLON: urgent surgical consultation — NPO, IV fluids, IV steroids, consider emergency colectomy if no improvement in 24–48h');
  }
  if (input.severity === 'acute_severe' || (input.isHospitalized && input.severity === 'severe')) {
    urgentFlags.push('ACUTE SEVERE UC (Truelove-Witts criteria): admit to hospital, IV methylprednisolone 60mg/day or hydrocortisone 400mg/day, surgical consultation on admission');
  }
  if (input.isSteroidRefractory && input.isHospitalized) {
    urgentFlags.push('STEROID-REFRACTORY ACUTE SEVERE UC: rescue therapy required — infliximab 5mg/kg or cyclosporine 2–4mg/kg IV. Surgical consultation mandatory.');
  }
  if (input.hasActiveTB) {
    urgentFlags.push('ACTIVE TB: all biologic therapy contraindicated');
    agentsToAvoid.push('All biologics and JAK inhibitors — contraindicated with active TB');
  }
  if (input.hasCongestiveHeartFailure) {
    urgentFlags.push('CHF (EF <35%): anti-TNF agents contraindicated');
    agentsToAvoid.push('Anti-TNF agents (infliximab, adalimumab, golimumab) — contraindicated in CHF with EF <35%');
  }
  if (input.hasDemyelinatingDisease) {
    urgentFlags.push('Demyelinating disease: anti-TNF agents contraindicated');
    agentsToAvoid.push('Anti-TNF agents — contraindicated with demyelinating disease');
  }
  if (input.hasJAKContraindication || input.hasThromboembolismHistory) {
    agentsToAvoid.push('JAK inhibitors (tofacitinib, upadacitinib, filgotinib) — contraindicated with DVT/PE history, high CV risk, or active malignancy (FDA Black Box Warning 2023)');
  }
  if (input.hasMalignancyHistory) {
    urgentFlags.push('Prior malignancy: avoid JAK inhibitors; prefer vedolizumab or IL-23 inhibitors');
    agentsToAvoid.push('JAK inhibitors — relative contraindication with prior malignancy');
  }

  // ─── Acute Severe UC Plan ─────────────────────────────────────────────────
  let acuteSevereUCPlan = 'Not applicable — not acute severe UC.';
  if (input.severity === 'acute_severe' || input.isHospitalized) {
    if (input.isSteroidRefractory && input.daysOnIVSteroids !== undefined && input.daysOnIVSteroids >= 3) {
      acuteSevereUCPlan =
        'STEROID-REFRACTORY ACUTE SEVERE UC (day 3–5 assessment): ' +
        'Rescue therapy options (ACG 2025 Strong Recommendation): ' +
        '1) Infliximab 5mg/kg IV — Oxford criteria (albumin <30g/L, CRP >45mg/L, >8 stools/day at day 3) predicts steroid failure. ' +
        '   Accelerated dosing (5mg/kg at 0, 1, 2 weeks) may be used in severe cases. ' +
        '2) Cyclosporine 2mg/kg IV continuous infusion — bridge to azathioprine/6-MP. ' +
        '3) Tofacitinib 10mg TID x8 weeks (oral JAK inhibitor — rapid onset, 3–5 days) — emerging evidence for rescue. ' +
        'Colectomy: if no response to rescue therapy at 4–7 days, or at any time if clinical deterioration.';
      recommendedAgents.push(
        'Infliximab 5mg/kg IV (rescue — CONSTRUCT trial)',
        'Cyclosporine 2mg/kg IV (rescue — bridge to thiopurine)',
        'Tofacitinib 10mg TID (oral rescue — emerging evidence)',
        'Surgical consultation (colectomy if rescue fails)'
      );
    } else {
      acuteSevereUCPlan =
        'ACUTE SEVERE UC — Initial management (Truelove-Witts protocol): ' +
        'IV methylprednisolone 60mg/day or hydrocortisone 100mg QID. ' +
        'NPO or clear liquids, IV fluids, DVT prophylaxis. ' +
        'Daily abdominal exam + plain X-ray (monitor for megacolon). ' +
        'Stool cultures + C. difficile PCR (exclude infectious trigger). ' +
        'Surgical consultation on admission. ' +
        'Assess response at day 3 (Oxford criteria) — plan rescue if no response.';
      recommendedAgents.push(
        'IV methylprednisolone 60mg/day or hydrocortisone 400mg/day',
        'DVT prophylaxis (LMWH)',
        'Stool cultures + C. difficile testing'
      );
    }
  }

  // ─── Induction Therapy ────────────────────────────────────────────────────
  let inductionTherapy = '';
  let biologicSelection = '';

  if (input.priorTherapy === 'none' || input.priorTherapy === 'on_5asa') {
    if (input.severity === 'mild' && (input.extent === 'proctitis' || input.extent === 'left_sided')) {
      inductionTherapy =
        'Mild-moderate proctitis/left-sided UC: topical 5-ASA is FIRST-LINE (ACG 2025 Strong Recommendation). ' +
        'Mesalamine suppository 1g/day (proctitis) or enema 4g/day (left-sided). ' +
        'Combination oral + topical 5-ASA is superior to either alone (ASCEND trials). ' +
        'Oral mesalamine 2.4–4.8g/day for left-sided/extensive disease.';
      recommendedAgents.push(
        'Mesalamine suppository 1g/day (proctitis)',
        'Mesalamine enema 4g/day (left-sided)',
        'Oral mesalamine 2.4–4.8g/day (MMX formulation preferred for once-daily dosing)',
        'Combination oral + topical 5-ASA (superior to monotherapy)'
      );
    } else if (input.severity === 'moderate' || input.severity === 'severe' || input.extent === 'extensive' || input.extent === 'pancolitis') {
      inductionTherapy =
        'Moderate-severe or extensive UC: biologic therapy recommended (AGA 2025 Strong Recommendation). ' +
        'Avoid prolonged steroid use — steroids are bridge therapy only. ' +
        'Early biologic initiation improves outcomes and reduces colectomy risk.';
      biologicSelection =
        'Biologic selection for moderate-severe UC (AGA 2025 mechanism-based approach): ' +
        '1) Vedolizumab (gut-selective integrin inhibitor) — GEMINI trials: preferred for UC due to gut selectivity, favorable safety profile, lower infection risk. ' +
        '2) Infliximab (anti-TNF) — ULTRA/ACT trials: rapid onset, preferred when quick response needed or EIM present. ' +
        '3) Adalimumab (anti-TNF SC) — convenient SC dosing. ' +
        '4) Golimumab (anti-TNF SC) — PURSUIT trials: approved for UC. ' +
        '5) Ustekinumab (IL-12/23) — UNIFI trial: effective, favorable safety. ' +
        '6) Risankizumab (IL-23) — INSPIRE trial: 40% clinical remission at 52 weeks. ' +
        '7) Mirikizumab (IL-23) — LUCENT trials: FDA approved 2023. ' +
        '8) Tofacitinib (JAK) — OCTAVE trials: rapid onset (days), oral. ' +
        '9) Upadacitinib (JAK1) — U-ACHIEVE: superior to adalimumab in head-to-head (QUARTZ trial). ' +
        '10) Ozanimod/Etrasimod (S1P modulators) — TRUE NORTH/ELEVATE trials.';
      recommendedAgents.push(
        'Vedolizumab 300mg IV (induction weeks 0, 2, 6, then Q8W) — preferred for UC',
        'Upadacitinib 45mg QD x8w then 30mg QD — oral JAK1 (superior to adalimumab in QUARTZ)',
        'Tofacitinib 10mg BID x8w then 5mg BID — oral JAK (rapid onset)',
        'Risankizumab 1200mg IV x3 then 360mg SC Q8W — IL-23 inhibitor',
        'Mirikizumab 300mg IV x3 then 200mg SC Q4W — IL-23 inhibitor (FDA 2023)',
        'Infliximab 5mg/kg IV Q8W — anti-TNF (rapid onset, EIM benefit)',
        'Ozanimod 0.92mg QD — S1P modulator (oral)'
      );
    } else {
      inductionTherapy =
        'Mild-moderate extensive UC: oral 5-ASA + consider biologic if inadequate response at 4–8 weeks. ' +
        'Oral mesalamine 4.8g/day (MMX formulation) + topical mesalamine for combination benefit.';
      recommendedAgents.push('Oral mesalamine 4.8g/day (MMX)', 'Topical mesalamine enema 4g/day', 'Prednisone 40–60mg/day (bridge if needed — taper over 8–12 weeks)');
    }
  } else if (input.priorTherapy === 'failed_5asa' || input.priorTherapy === 'failed_immunomodulator') {
    inductionTherapy =
      '5-ASA/immunomodulator failure: escalate to biologic therapy (AGA 2025 Strong Recommendation). ' +
      'Vedolizumab or anti-TNF as first biologic. ' +
      'Consider JAK inhibitor (upadacitinib) for rapid onset if needed.';
    biologicSelection =
      'First biologic selection post-5-ASA/immunomodulator failure: ' +
      'Vedolizumab preferred (gut-selective, favorable safety, most UC-specific data). ' +
      'Anti-TNF (infliximab) if rapid response needed or EIM present. ' +
      'Upadacitinib if oral therapy preferred and no JAK contraindications.';
    recommendedAgents.push(
      'Vedolizumab 300mg IV Q8W (preferred — gut-selective)',
      'Infliximab 5mg/kg IV Q8W (rapid onset)',
      'Upadacitinib 45mg QD x8w then 30mg QD (oral)',
      'Tofacitinib 10mg BID x8w (oral — rapid onset)'
    );
  } else if (input.priorTherapy === 'failed_anti_tnf') {
    inductionTherapy =
      'Anti-TNF failure: switch to non-anti-TNF mechanism. ' +
      'Assess reason for failure: primary non-response vs secondary loss of response (check drug levels/antibodies).';
    biologicSelection =
      'Post-anti-TNF options (AGA 2025): ' +
      '1) Vedolizumab — GEMINI: effective post-anti-TNF. ' +
      '2) Ustekinumab — UNIFI: effective post-anti-TNF. ' +
      '3) IL-23 inhibitors (risankizumab, mirikizumab) — effective post-anti-TNF. ' +
      '4) JAK inhibitors (upadacitinib, tofacitinib) — effective post-anti-TNF, rapid onset.';
    recommendedAgents.push(
      'Vedolizumab 300mg IV Q8W',
      'Upadacitinib 45mg QD x8w then 30mg QD',
      'Risankizumab 1200mg IV x3 then 360mg SC Q8W',
      'Mirikizumab 300mg IV x3 then 200mg SC Q4W',
      'Ustekinumab 260–520mg IV then 90mg SC Q8W'
    );
  } else if (input.priorTherapy === 'failed_vedolizumab' || input.priorTherapy === 'failed_multiple_biologics') {
    inductionTherapy =
      'Multiple biologic failure: consider remaining mechanisms. ' +
      'JAK inhibitors (upadacitinib, tofacitinib) effective post-multiple biologic failure. ' +
      'S1P modulators (ozanimod, etrasimod) as additional options. ' +
      'Colectomy discussion if refractory to ≥2 biologics.';
    biologicSelection =
      'Refractory UC options: ' +
      '1) Upadacitinib 45mg QD (JAK1 — effective post-multiple biologic failure). ' +
      '2) Tofacitinib 10mg BID (JAK — rapid onset). ' +
      '3) Ozanimod/Etrasimod (S1P modulators). ' +
      '4) Colectomy: curative option — total proctocolectomy with IPAA (ileal pouch-anal anastomosis).';
    recommendedAgents.push(
      'Upadacitinib 45mg QD x8w then 30mg QD (if no JAK contraindications)',
      'Tofacitinib 10mg BID x8w (rapid onset)',
      'Ozanimod 0.92mg QD (S1P modulator)',
      'Etrasimod 2mg QD (S1P modulator)',
      'Surgical consultation for colectomy discussion'
    );
    urgentFlags.push('Multiple biologic failure: colectomy discussion recommended — curative option with good quality-of-life outcomes');
  } else {
    inductionTherapy = 'Optimize current therapy. Check drug levels and anti-drug antibodies.';
    recommendedAgents.push('Therapeutic drug monitoring (TDM)');
  }

  // ─── Maintenance Therapy ──────────────────────────────────────────────────
  const maintenanceTherapy =
    'Maintenance principles (ACG 2025): ' +
    '1) All patients who achieve remission should continue maintenance therapy indefinitely. ' +
    '2) 5-ASA maintenance for mild-moderate UC (mesalamine 2g/day minimum). ' +
    '3) Biologic maintenance for moderate-severe UC or steroid-dependent disease. ' +
    '4) Steroids are NOT maintenance — taper and discontinue. ' +
    '5) Treat-to-target: endoscopic remission (Mayo endoscopic subscore 0–1) + fecal calprotectin <150μg/g.';

  // ─── Colectomy Consideration ──────────────────────────────────────────────
  let colectomyConsideration = '';
  if (input.hasPerforation || input.hasColonDilation) {
    colectomyConsideration = 'EMERGENCY COLECTOMY: perforation or toxic megacolon — immediate surgical intervention required.';
  } else if (input.isSteroidRefractory && input.isHospitalized) {
    colectomyConsideration =
      'Steroid-refractory acute severe UC: colectomy is curative and life-saving if rescue therapy fails. ' +
      'Total proctocolectomy with IPAA (ileal pouch-anal anastomosis) — excellent long-term outcomes. ' +
      'Discuss with patient before starting rescue therapy.';
  } else if (input.priorTherapy === 'failed_multiple_biologics') {
    colectomyConsideration =
      'Refractory UC after multiple biologic failures: colectomy is a reasonable and curative option. ' +
      'Quality of life after IPAA is generally good — comparable to medically managed remission. ' +
      'Multidisciplinary IBD team discussion recommended.';
  } else {
    colectomyConsideration = 'No immediate colectomy indication. Monitor disease activity and therapy response.';
  }

  // ─── Monitoring Plan ──────────────────────────────────────────────────────
  const monitoringPlan =
    'Monitoring (ACG 2025): ' +
    'Labs every 3 months: CBC, CMP, CRP, fecal calprotectin. ' +
    'Therapeutic drug monitoring (TDM) for anti-TNF: trough levels at 14 weeks, then annually or with loss of response. ' +
    'Colonoscopy at 6–12 months to assess endoscopic response (target Mayo endoscopic subscore 0–1). ' +
    'CRC surveillance: colonoscopy every 1–3 years after 8 years of extensive colitis. ' +
    'Annual skin exam (melanoma risk with anti-TNF + thiopurines). ' +
    'Bone density (DEXA) if on steroids >3 months.';

  if (nextSteps.length === 0) {
    nextSteps.push(
      'Colonoscopy to confirm diagnosis and assess endoscopic severity',
      'Baseline labs: CBC, CMP, CRP, ESR, fecal calprotectin, albumin',
      'Stool cultures + C. difficile PCR (exclude infectious trigger)',
      'Infectious screening before biologic: TB (IGRA), hepatitis B/C, HIV',
      'Vaccination update before immunosuppression',
      'IBD specialist referral'
    );
  }

  const rationale =
    `UC extent: ${input.extent.replace(/_/g, ' ')}. ` +
    `Severity: ${input.severity.replace(/_/g, ' ')}. ` +
    `Prior therapy: ${input.priorTherapy.replace(/_/g, ' ')}. ` +
    `Steroid dependent: ${input.isSteroidDependent ? 'Yes' : 'No'}. ` +
    `Steroid refractory: ${input.isSteroidRefractory ? 'Yes' : 'No'}. ` +
    `Hospitalized: ${input.isHospitalized ? 'Yes' : 'No'}.`;

  return {
    primaryRecommendation:
      input.severity === 'acute_severe' || input.isHospitalized
        ? 'ACUTE SEVERE UC: hospitalize, IV steroids, surgical consultation on admission. Rescue therapy if no response at day 3–5.'
        : input.severity === 'mild' && (input.extent === 'proctitis' || input.extent === 'left_sided') && input.priorTherapy === 'none'
        ? 'Mild proctitis/left-sided UC: topical + oral 5-ASA is first-line therapy.'
        : input.priorTherapy === 'failed_multiple_biologics'
        ? 'Refractory UC after multiple biologic failures: JAK inhibitor or S1P modulator; colectomy discussion recommended.'
        : 'Moderate-severe UC: biologic therapy indicated. Select based on mechanism, comorbidities, and patient preference.',
    inductionTherapy,
    maintenanceTherapy,
    biologicSelection,
    acuteSevereUCPlan,
    colectomyConsideration,
    urgentFlags,
    recommendedAgents,
    agentsToAvoid,
    monitoringPlan,
    nextSteps,
    evidenceLevel: 'A',
    rationale,
    references: [
      {
        citation: 'Rubin DT, et al. ACG Clinical Guideline: Ulcerative Colitis in Adults. Am J Gastroenterol. 2019;114(3):384-413.',
        pmid: '30840605',
        url: 'https://pubmed.ncbi.nlm.nih.gov/30840605/',
      },
      {
        citation: 'AGA Clinical Practice Guideline on the Management of Moderate to Severely Active Ulcerative Colitis. Gastroenterology. 2025. (Living guideline)',
        url: 'https://www.gastro.org/practice-guidance/practice-updates/aga-clinical-practice-guideline-uc',
      },
      {
        citation: 'Feagan BG, et al. Vedolizumab as Induction and Maintenance Therapy for Ulcerative Colitis (GEMINI I). N Engl J Med. 2013;369(8):699-710.',
        pmid: '23964932',
        url: 'https://pubmed.ncbi.nlm.nih.gov/23964932/',
      },
      {
        citation: 'Danese S, et al. Upadacitinib as Induction and Maintenance Therapy for Moderately to Severely Active Ulcerative Colitis (U-ACHIEVE). Lancet. 2022;399(10341):2113-2128.',
        pmid: '35644162',
        url: 'https://pubmed.ncbi.nlm.nih.gov/35644162/',
      },
      {
        citation: 'D\'Haens G, et al. Risankizumab as Induction and Maintenance Therapy for Ulcerative Colitis (INSPIRE). Lancet. 2023;401(10380):905-918.',
        pmid: '36870383',
        url: 'https://pubmed.ncbi.nlm.nih.gov/36870383/',
      },
      {
        citation: 'Sandborn WJ, et al. Tofacitinib as Induction and Maintenance Therapy for Ulcerative Colitis (OCTAVE). N Engl J Med. 2017;376(18):1723-1736.',
        pmid: '28467869',
        url: 'https://pubmed.ncbi.nlm.nih.gov/28467869/',
      },
    ],
  };
}

export function getUCSeverityColor(severity: UCSeverity): string {
  switch (severity) {
    case 'mild': return 'text-green-700 bg-green-50 border-green-200';
    case 'moderate': return 'text-yellow-700 bg-yellow-50 border-yellow-200';
    case 'severe': return 'text-orange-700 bg-orange-50 border-orange-200';
    case 'acute_severe': return 'text-red-700 bg-red-50 border-red-200';
  }
}
